def _config_ui(for_check=False):
    """Pure HTML generation: never read/save configuration or open host UI."""
    defaults = dict(_CHECK_DEFAULTS) if for_check else annotated_defaults()
    settings = {k: v for k, v in defaults.items() if not k.startswith("_")}
    sections = [("_CHECK", "Report options", list(settings))] if for_check else _SECTIONS
    notes = defaults if for_check else _NOTES
    groups, placed = [], set()
    # Append stragglers so a future control cannot disappear from the form.
    for _heading, title, keys in list(sections) + [("_OTHER", "Other settings", list(settings))]:
        fields = []
        for key in keys:
            if key in placed or key not in settings:
                continue
            placed.add(key)
            default = settings[key]
            choices = _UI_CHOICES.get(key)
            if isinstance(default, bool) and choices is None:
                choices = [True, False]
            fields.append({"key": key, "label": key.replace("_", " ").capitalize(),
                           "default": default, "help": notes.get("_" + key, ""),
                           "unit": _UI_UNITS.get(key, ""), "choices": choices,
                           "kind": "number" if isinstance(default, (int, float)) and not isinstance(default, bool) else "scalar",
                           "specials": [default.lower()] if isinstance(default, str) and default.lower() in ("auto", "orca") else []})
        if fields:
            groups.append({"title": title.strip("= "), "fields": fields})
    schema = {"title": _UI_PRODUCT + (" — report options" if for_check else " — settings"),
              "intro": ("This capability controls only the written guide. Run " + _UI_CHECK_NAME + " explicitly for setup checks. This form changes report options only; setup fixes run only from the Script action." if for_check else
                        "Run " + _UI_CHECK_NAME + " for setup and last-export diagnostics. Existing experimental controls are not a collision, strength or print-quality guarantee."),
              "defaults": defaults, "groups": groups, "check": for_check,
              "infill": _UI_INFILL, "release": _UI_PRODUCT + " v" + PLUGIN_VERSION,
              "changelog": CHANGELOG_RECENT}
    # A stored </script> must not escape the inert JSON payload.
    payload = json.dumps(schema, ensure_ascii=True).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return _SETTINGS_PAGE.replace("__SETTINGS_SCHEMA__", payload)


_SETUP_PROCESS_KEYS = ("enable_arc_fitting", "sparse_infill_density", "top_shell_layers",
                       "bottom_shell_layers", "spiral_mode", "detect_overhang_wall")


def _setup_snapshot():
    """Copy serialized primitive values; no live host references cross a prompt."""
    bundle = orca.host.preset_bundle()
    process = bundle.current_process_preset()
    name = process.name
    if not isinstance(name, str) or not name:
        raise ValueError("The active process has no readable identity")
    values = {key: process.config_value(key) for key in _SETUP_PROCESS_KEYS}
    if any(value is not None and not isinstance(value, str) for value in values.values()):
        raise ValueError("Unexpected process-setting representation")
    result = {"process": name, "dirty": bool(process.is_dirty), "values": values,
              "printer": None, "relative_e": None}
    try:
        printer = bundle.current_printer_preset()
        result["printer"] = str(printer.name)
        relative = printer.config_value("use_relative_e_distances")
        result["relative_e"] = relative if isinstance(relative, str) else None
    except BaseException:
        pass  # Read-only advice can still work without printer introspection.
    return result


def _setup_changes(snapshot):
    """Only a demonstrated parser prerequisite, never taste/geometry defaults."""
    arcs = snapshot["values"].get("enable_arc_fitting")
    if _UI_INFILL and arcs is not None and arcs.strip().lower() in ("1", "true"):
        return [("enable_arc_fitting", arcs, "0",
                 "Unlayered Infill rewrites linear G0/G1 moves, not G2/G3 arcs.")]
    return []


def _setup_assistant_lines():
    """Called ONLY by explicit Script execute, on the host's Script worker.

    Native message() is blocking, so confirmation and the staged transaction
    stay on that worker. No UI-thread callback, custom-config bridge message,
    pipeline hook, printer/filament transaction, named preset switch or save.
    """
    out = ["", "--- active setup / approved process changes ---",
           "Printer and filament profiles are read-only. No preset is saved."]
    try:
        before = _setup_snapshot()
    except BaseException as error:
        out += ["Active preset inspection is unavailable on this host; advice only.",
                "No preset edits attempted. Existing export behavior is unchanged.",
                "Host detail: " + str(error)]
        if _UI_INFILL:
            out.append("Relative E is required: Printer Settings > Use relative E distances (manual only).")
        return out
    out.append("Process preset: " + before["process"] + (" (unsaved edits)" if before["dirty"] else ""))
    for key, value in before["values"].items():
        out.append("  " + key + " = " + (json.dumps(value) if value is not None else "unavailable"))
    if _UI_INFILL:
        out += ["Printer (read-only): " + (before["printer"] or "unavailable"),
                "  use_relative_e_distances = " + json.dumps(before["relative_e"]),
                "Relative E is required. If off/unknown, change it manually in",
                "Printer Settings > Use relative E distances. This assistant will not change it.",
                "Sparse infill and solid skins above AND below are needed for waving.",
                "Density, skin counts and vase mode are advice only; choose them for your model."]
    else:
        out += ["Undahang needs exported Bridge paths over unsupported regions.",
                "It does not need a universal process-setting replacement; none is proposed.",
                "Detection/order/flow tuning stays in the main plugin's settings."]
    changes = _setup_changes(before)
    if not changes:
        out.append("No process-setting changes proposed. No transaction opened.")
        return out
    diff = [key + ": " + json.dumps(old) + " -> " + json.dumps(new) + "\n  " + reason
            for key, old, new, reason in changes]
    out += ["Proposed serialized process-setting diff (not yet applied):"] + diff
    try:
        begin = orca.host.preset.process.begin_update
        confirm = orca.host.ui.message
        if not callable(begin) or not callable(confirm):
            raise AttributeError("Missing staged preset API or native confirmation")
    except BaseException:
        out.append("Read-only fallback: staged process API/native confirmation unavailable; apply manually if wanted.")
        return out
    message = ("Active process preset: " + before["process"] +
               (" (already has unsaved edits)" if before["dirty"] else "") +
               "\n\n" + "\n\n".join(diff) +
               "\n\nApply ONLY these listed process changes? Yes approves the entire diff. "
               "No/Cancel changes nothing. Printer/filament profiles stay read-only. "
               "The process stays unsaved; save it yourself in Orca if wanted.")
    try:
        if confirm(text=message, title=_UI_PRODUCT + " — review process diff",
                   buttons="yes_no_cancel", icon="question") != "yes":
            out.append("Not approved / canceled. No transaction opened.")
            return out
        # Reject stale approval; never switch back to the reviewed preset.
        if _setup_snapshot() != before:
            out.append("Preset or reviewed values changed during review. Nothing applied; run setup again.")
            return out
        tx = begin()  # ACTIVE process only; never request a named preset switch.
        if (tx.target_name != before["process"] or tx.category != "process"
                or tx.selection_changed is not False or _setup_snapshot() != before):
            out.append("Active target changed before staging. Nothing committed; run setup again.")
            return out
        for key, _old, new, _reason in changes:
            if key != "enable_arc_fitting" or new != "0" or not _UI_INFILL:
                raise ValueError("Unapproved process-setting key/value")
            tx.set(key, new)
        # No await/callback/user interaction between the last snapshot and commit.
        if _setup_snapshot() != before:
            out.append("Reviewed values changed before commit. Nothing committed; run setup again.")
            return out
        result = tx.commit()
        after = _setup_snapshot()
        if (result.target_name != before["process"] or result.category != "process"
                or result.selection_changed is not False
                or list(result.keys) != [item[0] for item in changes]
                or after["process"] != before["process"]
                or any(after["values"].get(key) != new for key, _old, new, _reason in changes)):
            out.append("Host did not confirm the exact result. Inspect the active process; no retry or save requested.")
        else:
            out.append("Approved process changes applied in Orca's edited preset. UNSAVED: save the preset yourself if wanted.")
    except BaseException as error:
        out += ["Host did not confirm completion. No retry or automatic save was attempted.",
                "Inspect the active process before continuing. Host detail: " + str(error)]
    return out
# --- END SHARED ORCA SETTINGS UI ---


class UnlayeredInfill(orca.slicing.SlicingPipelineCapabilityBase):
    def get_name(self):
        return "Unlayered Infill"

    def get_default_config(self):
        # Annotated, so the JSON panel in Orca explains itself. The notes are
        # ignored on the way back in (see _cfg).
        return annotated_defaults()

    def has_config_ui(self):
        return True

    def get_config_ui(self):
        return _config_ui(False)

    def migrate_config_if_needed(self):
        """Orca's documented schema-migration hook.

        A config saved by an older release is missing every setting added
        since, and the Config panel shows that saved copy -- which is why
        `pattern` and `shape` were invisible to anyone who had used 0.3.4.
        Merge the new keys in, keep the user's values, write it back.
        """
        merged = _migrate_config(self, annotated_defaults(), self.get_name())
        _MIGRATED.add(self.get_name())
        try:
            version = self.get_config_version()
        except BaseException:
            version = ""
        return version, (merged if merged is not None else annotated_defaults())

    def execute(self, ctx):
        _log_loaded_once()
        # Belt and braces: the host is documented to call
        # migrate_config_if_needed(), but *when* is shown only by example and
        # is not verified on a real build. Doing it here too means one slice
        # is always enough to make the new settings appear in the panel.
        _migrate_once(self, annotated_defaults(), self.get_name())
        step = getattr(ctx, "step", None)
        step_name = getattr(step, "name", None) or str(step)

        # Every other step is somebody else's business.
        if step != orca.slicing.Step.psGCodePostProcess:
            if step_name not in _SEEN_STEPS:
                _SEEN_STEPS.add(step_name)
                _log(f"Unlayered Infill v{PLUGIN_VERSION}: pipeline step "
                     f"'{step_name}' seen (not ours, ignored)")
            return orca.ExecutionResult.success()

        cfg = _cfg(self)
        if not _truthy(cfg["enabled"]):
            return orca.ExecutionResult.success("Unlayered Infill: disabled")
        if npc is None:
            return orca.ExecutionResult.failure(
                orca.PluginResult.RecoverableError,
                "Unlayered Infill: the engine module is missing. Reinstall the "
                "plugin (the single-file build should have it inlined)."
                + (f"\nReason: {_ENGINE_ERROR}" if _ENGINE_ERROR else ""))

        path = getattr(ctx, "gcode_path", "") or ""
        if not path or not os.path.isfile(path):
            return orca.ExecutionResult.failure(
                orca.PluginResult.RecoverableError,
                f"Unlayered Infill: no G-code file to work on (gcode_path={path!r})")

        do_log = _truthy(cfg["log"])
        started = time.time()
        _log(f"Unlayered Infill v{PLUGIN_VERSION}: EXPORT STEP RUNNING",
             f"file         : {path}",
             f"settings     : amplitude={cfg['amplitude']!r} "
             f"frequency={cfg['frequency']!r} cell_mm={cfg['cell_mm']!r} "
             f"full_strength={cfg['full_strength']!r}",
             f"wave         : pattern={cfg['pattern']!r} "
             f"shape={cfg['shape']!r} angle={cfg['wave_angle']!r} "
             f"layer_phase={cfg['layer_phase']!r} "
             f"max_lift_mm={cfg['max_lift_mm']!r}",
             enabled=do_log)
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                lines = f.readlines()
            out, stats = npc.process(
                lines,
                amplitude_spec=cfg["amplitude"],
                frequency=cfg["frequency"],
                segment_mm=cfg["segment_mm"],
                require_relative_e=_truthy(cfg["require_relative_e"]),
                cell_mm=cfg["cell_mm"],
                blend_mm=cfg["blend_mm"],
                full_strength=_truthy(cfg["full_strength"]),
                pattern=cfg["pattern"],
                wave_angle=cfg["wave_angle"],
                shape=cfg["shape"],
                layer_phase=cfg["layer_phase"],
                max_lift_mm=cfg["max_lift_mm"],
            )
        except npc.NonPlanarError as e:
            # A clear, actionable stop -- surfaced as a slicing error. The seam
            # still demonstrably fired, so record that.
            _record_run(last_refused=str(e))
            _log("Unlayered Infill: REFUSED (file left untouched)",
                 *str(e).splitlines(), enabled=do_log)
            return orca.ExecutionResult.failure(
                orca.PluginResult.RecoverableError, f"Unlayered Infill: {e}")
        except Exception as e:  # never corrupt an export over a bug in here
            _log(f"Unlayered Infill: INTERNAL ERROR ({type(e).__name__}: {e})",
                 "the file was left untouched; this is a bug, please report it",
                 *traceback.format_exc().splitlines()[-6:], enabled=do_log)
            return orca.ExecutionResult.success(
                f"Unlayered Infill: skipped, file left untouched "
                f"({type(e).__name__}: {e})")

        # Does the waved result make the nozzle pass through anything it has
        # already printed? Checked on the OUTPUT, so it sees the real result
        # rather than the intention.
        collision_mode = str(cfg.get("collision_check", "warn")).strip().lower()
        if collision_mode not in npc.COLLISION_ACTIONS:
            collision_mode = "warn"
        collision_hits = []
        collision_worst = 0.0
        if collision_mode != "off" and not stats["already_processed"]:
            clearance, clearance_desc = npc.resolve_clearance(
                cfg.get("nozzle_clearance", "auto"), out)
            collision_worst, collision_hits, _checked = \
                npc.check_nozzle_clearance(
                    out, cell_mm=stats.get("cell_mm"), clearance=clearance)
            if collision_hits:
                _record_run(last_collision=collision_worst)
                _log(f"Unlayered Infill: NOZZLE CLEARANCE -- "
                     f"{len(collision_hits)}+ place(s) where the nozzle passes "
                     f"under printed material (worst {collision_worst:.3f} mm)",
                     f"clearance    : {clearance_desc}",
                     *collision_hits,
                     "This is what the max_lift_mm ceiling is for. Lower the "
                     "amplitude, or set max_lift_mm, or set collision_check "
                     "to off if your machine tolerates it.",
                     enabled=do_log)
                if collision_mode == "refuse":
                    return orca.ExecutionResult.failure(
                        orca.PluginResult.RecoverableError,
                        f"Unlayered Infill: refused -- the waved result would "
                        f"drive the nozzle up to {collision_worst:.3f} mm into "
                        f"material it has already printed. Lower the "
                        f"amplitude or set max_lift_mm. (collision_check)")

        if stats["already_processed"]:
            # Orca ran the export step twice for one slice. The first call did
            # the work; waving again would double every displacement.
            _record_run(last_skipped="already waved")
            _log("Unlayered Infill: already waved, left as is",
                 "Orca ran the export step twice for one slice; doing it again "
                 "would double every displacement", enabled=do_log)
            return orca.ExecutionResult.success(
                "Unlayered Infill: already applied to this file, left as is")

        if not stats["moves"]:
            _record_run(last_moves=0, last_sections=stats["sections"])
            if stats["sections"] == 0:
                why = ("no sparse-infill sections in this file -- infill "
                       "density 0%, or an all-wall part")
            elif stats["solid_layers"] == 0:
                why = ("infill found but no solid skin -- the wave tapers "
                       "against the skin above and below, so check that "
                       "top/bottom shell layers are not 0")
            else:
                why = ("infill and skin both found, but no infill move sits "
                       "between skin above AND below in its own column")
            _log("Unlayered Infill: NOTHING CHANGED", *_fmt_stats(stats),
                 f"reason       : {why}", enabled=do_log)
            return orca.ExecutionResult.success(
                "Unlayered Infill: nothing to do — no sparse infill was found "
                "between two solid skins. Thin all-wall parts, 0% infill, and "
                "parts with no top/bottom solid layers have nothing to wave.")

        try:
            tmp_path = os.path.join(
                os.path.dirname(os.path.abspath(path)) or ".",
                f".{os.path.basename(path)}.{os.getpid()}.tmp")
            try:
                with open(tmp_path, "w", encoding="utf-8") as f:
                    f.writelines(out)
                os.replace(tmp_path, path)
            except OSError:
                try:
                    if os.path.exists(tmp_path):
                        os.remove(tmp_path)
                except OSError:
                    pass
                with open(path, "w", encoding="utf-8") as f:
                    f.writelines(out)
        except Exception as e:
            _log(f"Unlayered Infill: COULD NOT WRITE THE G-CODE ({e})",
                 enabled=do_log)
            return orca.ExecutionResult.failure(
                orca.PluginResult.RecoverableError,
                f"Unlayered Infill: could not write the G-code: {e}")

        _record_run(last_moves=stats["moves"], last_sections=stats["sections"],
                    last_segments=stats["segments"], last_skipped=None,
                    last_refused=None, last_columns=stats["solid_columns"])
        _log("Unlayered Infill: DONE -- the G-code was rewritten",
             *_fmt_stats(stats),
             f"took         : {time.time() - started:.1f} s",
             "NOTE: Orca's 3D preview will NOT show this. To see it, drag the "
             "exported .gcode back into OrcaSlicer.", enabled=do_log)
        return orca.ExecutionResult.success(
            f"Unlayered Infill: {stats['moves']} infill move(s) across "
            f"{stats['sections']} section(s) rewritten as {stats['segments']} "
            f"wavy segment(s); amplitude {stats['amplitude_desc']}, "
            f"largest Z offset {stats['max_wiggle']:.3f} mm")


_CHECK_DEFAULTS = {
    "_READ_ME": (
        "Keys starting with _ are notes, not settings -- the plugin ignores "
        "them. This item reports whether Unlayered Infill is working and "
        "then explains every setting of the main Unlayered Infill capability."
    ),
    "_settings_guide": (
        "Show the full explanation of every Unlayered Infill setting after "
        "the diagnostics. Set false once you know them and you will get just "
        "the short status report."
    ),
    "settings_guide": True,
}


class UnlayeredInfillCheck(orca.script.ScriptPluginCapabilityBase):
    def get_name(self):
        return "Unlayered Infill - Check setup"

    def get_default_config(self):
        return dict(_CHECK_DEFAULTS)

    def has_config_ui(self):
        return True

    def get_config_ui(self):
        return _config_ui(True)

    def migrate_config_if_needed(self):
        merged = _migrate_config(self, dict(_CHECK_DEFAULTS), self.get_name())
        _MIGRATED.add(self.get_name())
        try:
            version = self.get_config_version()
        except BaseException:
            version = ""
        return version, (merged if merged is not None else dict(_CHECK_DEFAULTS))

    def _want_guide(self):
        try:
            raw = json.loads(self.get_config() or "{}")
        except (AttributeError, TypeError, ValueError):
            return True
        value = raw.get("settings_guide", True)
        if isinstance(value, str):
            return value.strip().lower() not in ("false", "0", "no", "off")
        return bool(value)

    def execute(self):
        _log_loaded_once()
        _migrate_once(self, dict(_CHECK_DEFAULTS), self.get_name())
        lines = [f"Unlayered Infill v{PLUGIN_VERSION} -- setup check"]
        lines.append(f"engine: {'inlined/available' if npc else 'MISSING (rebuild)'}")
        if _ENGINE_ERROR:
            lines.append(f"engine load error: {_ENGINE_ERROR}")
        if npc is None:
            return orca.ExecutionResult.failure(
                orca.PluginResult.RecoverableError,
                "The engine module is missing — reinstall the plugin."
                + (f"\nReason: {_ENGINE_ERROR}" if _ENGINE_ERROR else ""))
        lines.append("dependencies: none (pure standard library, no restart needed)")
        lines.append("")
        st = _load_state()
        lines.append("--- what the last export actually did ---")
        if not st.get("seam_ever"):
            lines.append("The G-code step has NEVER RUN on this machine.")
            lines.append("")
            lines.append("Select it here:")
            lines.append("  Process preset -> Others -> Slicing Pipeline Plugin")
            lines.append("  -> Unlayered Infill")
            lines.append("")
            lines.append("That one field drives every step, including the")
            lines.append("G-code export step this plugin uses. Then slice,")
            lines.append("export, and run this check again.")
        elif st.get("last_refused"):
            lines.append("The G-code step ran, but the plugin refused:")
            lines.append(f"  {st['last_refused']}")
        else:
            lines.append(f"The G-code step ran: {st.get('last_moves', 0)} infill "
                         f"move(s) across {st.get('last_sections', 0)} section(s)")
            if not st.get("last_moves"):
                lines.append("...but there was no sparse infill between two")
                lines.append("solid skins to wave. Check infill density is not")
                lines.append("0% and the part has top/bottom solid layers.")
        lines.append("")
        lines.append("Your printer must use RELATIVE extrusion:")
        lines.append("  Printer Settings -> Advanced -> Use relative E distances")
        lines.append("Otherwise the plugin refuses to run rather than corrupt")
        lines.append("the file.")
        lines.append("")
        backup = _settings_backup()
        lines.append("")
        lines.append("--- your settings are backed up ---")
        if backup:
            changed = {k: v for k, v in backup["values"].items()
                       if k in _DEFAULTS and _DEFAULTS[k] != v}
            lines.append(f"{len(backup['values'])} setting(s) remembered, "
                         f"saved by v{backup.get('version', '?')} on "
                         f"{backup.get('saved_at', '?')}.")
            if changed:
                lines.append("Non-default values held: "
                             + ", ".join(f"{k}={json.dumps(v)}"
                                         for k, v in sorted(changed.items())))
            else:
                lines.append("All of them are at this build's defaults.")
            lines.append("If the Config panel ever comes back empty or reset,")
            lines.append("set restore_backup to true and slice once; these")
            lines.append("values go back and the flag returns to false.")
        else:
            lines.append("Nothing remembered yet -- a backup is taken every")
            lines.append("time this plugin runs.")
        lines.append("--- not seeing all the settings? ---")
        lines.append(f"This build has {len(_DEFAULTS)} tuning controls. The form")
        lines.append("shows all of them in labelled groups, even if an older")
        lines.append("saved JSON copy is missing newly added keys.")
        lines.append("Missing keys use defaults; existing values are kept.")
        lines.append("The JSON fallback is on the same page. A preset override")
        lines.append("takes precedence over the global Plugins configuration.")
        lines.append("Check the scope banner before saving or restoring.")
        lines.append("Restore defaults resets GLOBAL values only in global Config;")
        lines.append("Remove override in preset Config falls back to global values.")
        lines.append("Both are explicit actions, not a required update step.")
        lines.append("If the running version above is old, update the plugin")
        lines.append("and fully quit/reopen OrcaSlicer, not just its window.")
        lines.append("")
        lines.append("--- log ---")
        lp = log_path()
        lines.append("Every run is appended without approval prompts to:")
        lines.append(f"  {lp}")
        if os.path.isfile(lp):
            try:
                size = os.path.getsize(lp)
                lines.append(f"  (exists, {size} bytes -- open it in Notepad)")
            except OSError:
                pass
        else:
            lines.append("  (not created yet -- it appears the first time the")
            lines.append("   plugin loads or runs)")
        lines.append("")
        lines.append("--- two things that are NOT bugs ---")
        lines.append("1. The 3D preview never shows this plugin's work. Orca")
        lines.append("   draws the preview from the slice; this runs after,")
        lines.append("   at export. Drag the exported .gcode back into Orca")
        lines.append("   to see the result.")
        lines.append("2. Verify with 'Export G-code file' and reopen that file.")
        lines.append("   Print/Send handling depends on the installed Orca build;")
        lines.append("   this report does not certify those paths.")
        lines.append("")
        lines.append("EXPERIMENTAL: check the G-code Preview and print a small")
        lines.append("test part before trusting it on a long job.")
        lines.append("")
        lines.append("--- what changed recently ---")
        lines.extend(CHANGELOG_RECENT.splitlines())
        lines.append("")
        lines.append("Full history: https://docs.google.com/document/d/1XTRAFNzKzrKLyo5BrGinvtbg-RQoNAymHIWEg6Ba7io/edit?usp=drivesdk")
        lines.extend(_setup_assistant_lines())
        if self._want_guide():
            lines.append("")
            lines.extend(settings_guide_lines())
            lines.append("To hide this guide, set settings_guide to false in")
            lines.append("this item's own settings.")
        return orca.ExecutionResult.success("\n".join(lines))


@orca.plugin
class UnlayeredInfillPlugin(orca.base):
    def register_capabilities(self):
        orca.register_capability(UnlayeredInfill)
        orca.register_capability(UnlayeredInfillCheck)
